  const svgProduct = '<svg viewBox="0 0 32 32" aria-hidden="true"><rect x="7" y="5" width="18" height="21" rx="2" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M10 9h12M10 13h12M12 19h8M10 26v3M22 26v3" stroke="currentColor" stroke-width="1.5"/><circle cx="23" cy="20" r="1" fill="currentColor"/></svg>';
  const initialLayout = Number(new URLSearchParams(location.search).get('layout'));
  const state = {layout:initialLayout>=1&&initialLayout<=5?initialLayout:1,platform:'jd',shop:'all',start:'2026-09-23',end:'2026-09-29',grain:'day',compare:true,year:false,scenario:'complete',metric:'amount',selectedDate:null,detailShop:null,search:'',objectTab:'product',chosenObject:null,matrixShop:'jd-a',chapter:0,reportTab:'html',tileOrder:['overview','trend','shops','products','diagnostic','capabilities','sources'],tileWidths:{overview:12,trend:8,shops:4,products:12,diagnostic:6,capabilities:6,sources:12}};
  const $ = s => document.querySelector(s);
