  const shift = (d,n) => {const value=utc(d);value.setUTCDate(value.getUTCDate()+n);return dateStr(value)};
  const dateList = (s,e) => {const values=[];for(let d=s;d<=e&&values.length<367;d=shift(d,1))values.push(d);return values};
