    return {shop,date,promo,product,spend,revenue:Math.round(spend*roas),clicks:scenario==='missing'?null:clicks,impressions:Math.round(clicks/(.028+index*.006)),orders:scenario==='zero'?0:Math.round(clicks*.035),payment:Math.round(spend*(10.5+index*1.7))};
