    const sum=(list,key)=>list.reduce((a,r)=>a+(r[key]??0),0);
    const spend=ads.length?sum(ads,'spend'):null,revenue=ads.length?sum(ads,'revenue'):null,clicks=!ads.length||ads.some(r=>r.clicks===null)?null:sum(ads,'clicks'),impressions=ads.length?sum(ads,'impressions'):null,orders=ads.length?sum(ads,'orders'):null;
