    const weights=state.objectTab==='plan'?[.46,.33,.21]:[.38,.28,.22,.12];
    return names.map((name,i)=>({key:`${state.platform}|${shop.id}|${state.objectTab}|${1001+i}`,shop,id:`${state.objectTab==='plan'?'P':'K'}-${1001+i}`,name,spend:Math.round(s.spend*weights[i]),revenue:Math.round(s.revenue*weights[i]),clicks:s.clicks===null?null:Math.round(s.clicks*weights[i]),orders:Math.round(s.orders*weights[i]),weight:weights[i],coverage:`${s.adCount}/${s.expected} 日`,dimension:state.objectTab==='plan'?'计划 ID':'关键词 ID',change:(i%2===0?1:-1)*(11+i*2),unit:`U-${2001+i}`,match:i===3?'不适用':['精确匹配','短语匹配','广泛匹配'][i%3]}));
